probes.append({'cue':'Actual UI answer position','subgroup':'exact delivered batch radio fields','scope':'other_recognizable_subgroup','strategy':'Choose displayed position '+str(pos),'correct':k,'total':len(rendered),'baseline':0.2,'disposition':'not_predictive','conclusion':'Baseline is five-way uniform guessing. Counts come from actual rendered DOM; no one displayed position answers all radios. Future task/item IDs change UI ordering.','sample_refs':['render-inspection.json','batch-records.json']})
probes.append({'cue':'Prompt is a constant times ln x','subgroup':'all 46 independently checked examples','scope':'overall','strategy':'Preserve the complete coefficient and replace ln x by 1/x','correct':46,'total':46,'baseline':0.0,'disposition':'intended_skill','conclusion':'The comparison strategy always answering 1/x succeeds in 0/46 tested cases. Preserving c and differentiating ln is exactly the canonical operation, not an incidental bypass.','sample_refs':['math-results.json','independent-records.json','batch-records.json','counterfactual-records.json']})
